def bubble_sort(array):
    n = len(array)
    for i in range(n):
        for j in range(0, n - i - 1):
            if array[j] > array[j + 1]:
                array[j], array[j + 1] = (array[j + 1], array[j])
    return array

def insertion_sort(lst):
    for i in range(1, len(lst)):
        while i > 0 and lst[i] < lst[i - 1]:
            lst[i], lst[i - 1] = (lst[i - 1], lst[i])
            i -= 1
    return lst

def selection_sort(arr):
    sorted_arr = []
    def find_min_index(arr):
        if not arr:
            raise ValueError('array is empty')
        min_index = 0
        for i, item in enumerate(arr):
            if item <= arr[min_index]:
                min_index = i
        return min_index
    for _ in range(len(arr)):
        index = find_min_index(arr)
        sorted_arr.append(arr.pop(index))
    return sorted_arr

def quicksort(array):
    if len(array) < 2:
        return array
    else:
        pivot = array[0]
        less = [i for i in array[1:] if i <= pivot]
        greater = [i for i in array[1:] if i > pivot]
        return quicksort(less) + [pivot] + quicksort(greater)

def counting_sort(arr, max_num_in_array=None):
    if not arr:
        return arr
    if max_num_in_array is None:
        max_num_in_array = max(arr)
    counts = [0] * (max_num_in_array + 1)
    for num in arr:
        counts[num] += 1
    i = 0
    for num, count in enumerate(counts):
        for _ in range(count):
            arr[i] = num
            i += 1
    return arr

def linear_search(array, target):
    for i, item in enumerate(array):
        if item == target:
            return i
    return -1

def binary_search(sorted_array, target):
    low = 0
    high = len(sorted_array) - 1
    while low <= high:
        mid = (low + high) // 2
        if target == sorted_array[mid]:
            return mid
        elif target < sorted_array[mid]:
            high = mid - 1
        elif target > sorted_array[mid]:
            low = mid + 1
    return -1

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def lcm(num1, num2):
    if num1 > num2:
        num1, num2 = (num2, num1)
    for x in range(num2, num1 * num2 + 1, num2):
        if x % num1 == 0:
            return x

def sieve_of_eratosthenes(n):
    """function to find and print prime numbers up
    to the specified number

    :param n: upper limit for finding all primes less than this value"""
    primes = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if primes[p]:
            for i in range(p * 2, n + 1, p):
                primes[i] = False
        p += 1
    primes = [element for element in range(2, n + 1) if primes[element]]
    return primes

def prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2
    if n > 2:
        factors.append(n)
    return factors

def factorial(number):
    if number == 0 or number == 1:
        return 1
    answer = number * factorial(number - 1)
    return answer

def rec_fib(n):
    if n == 1:
        return 1
    elif n == 0:
        return 0
    else:
        return rec_fib(n - 1) + rec_fib(n - 2)

def pow(a, b):
    """Same as a ** b."""
    return a ** b

def bin2dec(x):
    """Convert binary string to decimal number.
    For instance: '11' -> 3"""
    return int(x, 2)

def is_perfect_square(num):
    """Given a positive integer num, write a function which returns True if num is a perfect square else False.

    Note: Do not use any built-in library function such as `sqrt`.

    :type num: int
    :rtype: bool"""
    i = 0
    while i * i < num:
        i += 1
    if i * i == num:
        return True
    else:
        return False

def factors(number):
    """Find all of the factors of a number and return it as a list.

    :type number: integer
    :param number: The number to find the factors for."""
    if not isinstance(number, int):
        raise TypeError('Incorrect number type provided. Only integers are accepted.')
    factors = []
    for i in range(1, number + 1):
        if number % i == 0:
            factors.append(i)
    return factors

def sum_of_squares(number):
    numerator = number * (number + 1) * (2 * number + 1)
    return numerator / 6

def get_char_frequency(string: str) -> Dict[str, int]:
    freq = {}
    for char in string:
        if char not in freq:
            freq[char] = 0
        freq[char] += 1
    return freq

def is_isogram(string):
    characters_lower = [char.lower() for char in string if char.isalpha()]
    return len(set(characters_lower)) == len(characters_lower)

def to_snake(camel):
    """TimeSkill -> time_skill"""
    if not camel:
        return camel
    return ''.join(('_' + x if 'A' <= x <= 'Z' else x for x in camel)).lower()[camel[0].isupper():]

def commonprefix(m):
    """Given an iterable of strings, returns the longest common leading substring"""
    if not m:
        return ''
    s1 = min(m)
    s2 = max(m)
    for i, c in enumerate(s1):
        if c != s2[i]:
            return s1[:i]
    return s1

def is_paired(input_string):
    counterparts = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in input_string:
        if char in counterparts.values():
            stack.append(char)
        elif char in counterparts:
            if not stack:
                return False
            if stack.pop() != counterparts[char]:
                return False
    return not stack

def median(iterable, sort=True):
    """Returns the value that separates the lower half from the higher half of values in the list.
    """
    s = sorted(iterable) if sort is True else list(iterable)
    n = len(s)
    if n == 0:
        raise ValueError('median() arg is an empty sequence')
    if n % 2 == 0:
        return float(s[n // 2 - 1] + s[n // 2]) / 2
    return s[n // 2]

def flatten(seqs):
    """Flatten a sequence of sequences into a single flat list."""
    return sum(seqs, [])

def rotate_array_1(arr, k, right=True):
    n = len(arr)
    right %= n
    if right:
        k = n - k
    return arr[k:] + arr[:k]

def merge(a, b):
    """Function to merge
    two arrays / separated lists

    :param a: Array 1
    :param b: Array 2
    :return: merged arrays"""
    c = []
    while len(a) != 0 and len(b) != 0:
        if a[0] < b[0]:
            c.append(a[0])
            a.remove(a[0])
        else:
            c.append(b[0])
            b.remove(b[0])
    if len(a) == 0:
        c += b
    else:
        c += a
    return c

def two_sum(array: list[int], target: int) -> tuple[int, int] | None:
    """Find two indices whose corresponding values sum to target.

    Args:
        array: List of integers to search.
        target: Desired sum of two elements.

    Returns:
        Tuple of (index1, index2) if a pair is found, or None otherwise.

    Examples:
        >>> two_sum([2, 7, 11, 15], 9)
        (0, 1)"""
    seen = {}
    for index, num in enumerate(array):
        if num in seen:
            return (seen[num], index)
        else:
            seen[target - num] = index
    return None

def transpose(matrix: list[list[int]]) -> list[list[int]]:
    matrix[:] = [list(x) for x in zip(*matrix)]
    return matrix

def dot_product(x, y):
    """Return the sum of the element-wise product of vectors x and y."""
    return sum((_x * _y for _x, _y in zip(x, y)))

def is_sorted(a):
    n = len(a)
    for i in range(0, n - 1):
        if a[i] > a[i + 1]:
            return False
    return True

def permutation(lst):
    if len(lst) == 0:
        return []
    if len(lst) == 1:
        return [lst]
    l = []
    for i in range(len(lst)):
        m = lst[i]
        rem_lst = lst[:i] + lst[i + 1:]
        for p in permutation(rem_lst):
            l.append([m] + p)
    return l

def countOf(a, b):
    """Return the number of items in a which are, or which equal, b."""
    count = 0
    for i in a:
        if i is b or i == b:
            count += 1
    return count

def height(root):
    if root is None:
        return 0
    else:
        return 1 + max(height(root.left), height(root.right))

def inorder_rec(root, res=None):
    """Recursive Implementation"""
    if root is None:
        return []
    if res is None:
        res = []
    inorder_rec(root.left, res)
    res.append(root.val)
    inorder_rec(root.right, res)
    return res

def search_iterative(root, val):
    while root:
        if val > root.val:
            root = root.right
        elif val < root.val:
            root = root.left
        else:
            return True
    return False

def count_nodes(root):
    if root is None:
        return 0
    return count_nodes(root.left) + count_nodes(root.right) + 1

def rows(row_count, previous_row=[1]):
    if row_count < 0:
        raise ValueError('number of rows is negative')
    elif row_count == 0:
        return []
    temp_row = previous_row + [0]
    new_row = list(map(sum, zip(temp_row, temp_row[::-1])))
    return [previous_row] + rows(row_count - 1, new_row)

def lcs(s1, s2):
    cols = len(s1) + 1
    rows = len(s2) + 1
    t = [[0 for i in range(cols)] for i in range(rows)]
    max_length = 0
    for i in range(1, rows):
        for j in range(1, cols):
            if s2[i - 1] == s1[j - 1]:
                t[i][j] = 1 + t[i - 1][j - 1]
            else:
                t[i][j] = max(t[i - 1][j], t[i][j - 1])
            max_length = max(max_length, t[i][j])
    return max_length

def brick_sort(arr):
    """Performs an odd-even in-place sort, which is a variation of a bubble
    sort.

    https://www.geeksforgeeks.org/odd-even-sort-brick-sort/

    :param arr: the array of values to sort
    :return: the sorted array"""
    is_sorted = False
    while not is_sorted:
        is_sorted = True
        for i in range(1, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
        for i in range(0, len(arr) - 1, 2):
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = (arr[i + 1], arr[i])
                is_sorted = False
    return arr

def is_integer(string):
    try:
        int(string)
        return True
    except ValueError:
        return False

def is_subsequence(needle, haystack):
    """Are all the elements of needle contained in haystack, and in the same order?
    There may be other elements interspersed throughout"""
    it = iter(haystack)
    for element in needle:
        if element not in it:
            return False
    return True

def longest_palindromic_substring_DP(s):
    S = [[False for i in range(len(s))] for j in range(len(s))]
    max_palindrome = ''
    for i in range(len(s))[::-1]:
        for j in range(i, len(s)):
            S[i][j] = s[i] == s[j] and (j - i < 3 or S[i + 1][j - 1])
            if S[i][j] and j - i + 1 > len(max_palindrome):
                max_palindrome = s[i:j + 1]
    return max_palindrome

def to_int(value: Callable[[], int] | int) -> int:
    """Turn callable or int into int."""
    if callable(value):
        return to_int(value())
    else:
        return int(value)

def is_unique(seq):
    """Return true if seq has no duplicate elements."""
    return len(seq) == len(set(seq))

def list_difference(left, right):
    """Take the not-in-place difference of two lists (left - right), similar to sets but preserving order."""
    blocked = set(right)
    difference = []
    for item in left:
        if item not in blocked:
            blocked.add(item)
            difference.append(item)
    return difference

def unzip2(pairs):
    lst1, lst2 = ([], [])
    for x1, x2 in pairs:
        lst1.append(x1)
        lst2.append(x2)
    return (lst1, lst2)

def argmax(l, f=None):
    """http://stackoverflow.com/questions/5098580/implementing-argmax-in-python"""
    if f:
        l = [f(i) for i in l]
    return max(enumerate(l), key=lambda x: x[1])[0]

def _prod(a):
    p = 1
    for x in a:
        p *= x
    return p

def flat(x):
    if isinstance(x, list):
        return [k for a in x for k in flat(a)]
    return [x]

def LIS(arr):
    n = len(arr)
    if n == 0:
        return 0
    res = 1
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = 1
        for j in range(0, i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)
        res = max(res, dp[i])
    return res

def majority_element(arr: List[int]) -> Optional[int]:
    length = len(arr)
    if not length:
        return
    elif length < 3:
        return arr[0]
    frequency = {}
    for elem in arr:
        if elem not in frequency:
            frequency[elem] = 0
        frequency[elem] += 1
    for elem in frequency:
        if frequency[elem] > length // 2:
            return elem

def count_divisors(n):
    n_divisors = 1
    i = 2
    while i * i <= n:
        multiplicity = 0
        while n % i == 0:
            n //= i
            multiplicity += 1
        n_divisors *= multiplicity + 1
        i += 1
    if n > 1:
        n_divisors *= 2
    return n_divisors

def iroot(n, k=2):
    if n == 0:
        return 0
    if n < 0:
        return -iroot(-n, k) if k & 1 else None
    u = 1 << -(-n.bit_length() // k)
    s = u + 1
    while u < s:
        s = u
        t = (k - 1) * s + n // s ** (k - 1)
        u = t // k
    return s

def hex2dec(x):
    """Convert hexadecimal string to decimal number.
    For instance: '1a' -> 26"""
    return int(x, 16)

def lerp(a, b, t):
    """Returns the linear interpolation between a and b at time t between 0.0-1.0.
    For example: lerp(100, 200, 0.5) => 150."""
    if t < 0.0:
        return a
    if t > 1.0:
        return b
    return a + (b - a) * t

def _round_multiple(x: int, mult: int=None) -> int:
    """Calc `x` to nearest multiple of `mult`."""
    return int(x / mult + 0.5) * mult if mult is not None else x

def power(x, y, p):
    res = 1
    x = x % p
    while y > 0:
        if y & 1 == 1:
            res = res * x % p
        y = y >> 1
        x = x * x % p
    return res

def _reversedict(d):
    """Internal helper for generating reverse mappings; given a
    dictionary, returns a new dictionary with keys and values swapped."""
    return dict(list(zip(list(d.values()), list(d.keys()))))

def frequencies(word_list):
    """Takes a list of words and returns a dictionary associating
    words with frequencies of occurrence"""
    word_freqs = {}
    for w in word_list:
        if w in word_freqs:
            word_freqs[w] += 1
        else:
            word_freqs[w] = 1
    return word_freqs

def zipdict(keys, vals):
    """Creates a dict with keys mapped to the corresponding vals."""
    return dict(zip(keys, vals))

def is_adjacency_matrix_symmetric(adjacency_matrix):
    """Determines if an adjacency matrix is symmetric.
    Ref: http://mathworld.wolfram.com/SymmetricMatrix.html"""
    num_columns = len(adjacency_matrix)
    for column in adjacency_matrix:
        if len(column) != num_columns:
            return False
    max_i = 0
    for j in range(num_columns):
        for i in range(max_i):
            if i == j:
                continue
            if adjacency_matrix[j][i] != adjacency_matrix[i][j]:
                return False
        max_i += 1
    return True

def time_to_seconds(t):
    """Convert time H:M:S to seconds"""
    l = list(map(int, t.split(':')))
    return sum((n * sec for n, sec in zip(l[::-1], (1, 60, 3600))))

def coin_change_1(coins, amount):
    if amount == 0:
        return 0
    if len(coins) == 0:
        return -1
    max_value = amount + 1
    dp = [max_value for i in range(max_value)]
    dp[0] = 0
    for i in range(1, max_value):
        for c in coins:
            if c <= i:
                dp[i] = min(dp[i], dp[i - c] + 1)
    if dp[amount] == max_value:
        return -1
    return dp[amount]

def unique_paths(n, m):
    m, n = (min(m, n), max(m, n))
    lvl = m + n - 2
    pos = m - 1
    comb = 1
    for i in range(1, pos + 1):
        comb *= lvl
        comb /= i
        lvl -= 1
    return int(comb + 0.001)

def luhn_check(card_number):
    """checks to make sure that the card passes a luhn mod-10 checksum"""
    sum = 0
    num_digits = len(card_number)
    oddeven = num_digits & 1
    for count in range(0, num_digits):
        digit = int(card_number[count])
        if not count & 1 ^ oddeven:
            digit *= 2
        if digit > 9:
            digit -= 9
        sum += digit
    return sum % 10 == 0

def preorder_rec(root, res=None):
    """Recursive Implementation"""
    if root is None:
        return []
    if res is None:
        res = []
    res.append(root.val)
    preorder_rec(root.left, res)
    preorder_rec(root.right, res)
    return res

def postorder_rec(root, res=None):
    if root is None:
        return []
    if res is None:
        res = []
    postorder_rec(root.left, res)
    postorder_rec(root.right, res)
    res.append(root.val)
    return res

def level_order(root):
    ans = []
    if not root:
        return ans
    level = [root]
    while level:
        current = []
        new_level = []
        for node in level:
            current.append(node.val)
            if node.left:
                new_level.append(node.left)
            if node.right:
                new_level.append(node.right)
        level = new_level
        ans.append(current)
    return ans

def is_same_tree(p, q):
    if p is None and p == q:
        return True
    if p is None or q is None:
        return False
    if p.val != q.val:
        return False
    if not is_same_tree(p.left, q.left):
        return False
    if not is_same_tree(p.right, q.right):
        return False
    return True

def detect_cycle(head):
    if not head or not head.next:
        return False
    slow = head
    fast = head.next
    while slow != fast:
        if fast == None or fast.next == None:
            return False
        slow = slow.next
        fast = fast.next.next
    return True

def remove(head, val):
    while head and head.val == val:
        head = head.next
    if not head:
        return None
    curr = head
    while curr.next:
        if curr.next.val == val:
            curr.next = curr.next.next
        else:
            curr = curr.next
    return head

def is_cyclic(graph):
    """Return True if the directed graph g has a cycle. The directed graph
    should be represented as a dictionary mapping of edges for each node."""
    path = set()
    def visit(vertex):
        path.add(vertex)
        for neighbour in graph.get(vertex, ()):
            if neighbour in path or visit(neighbour):
                return True
        path.remove(vertex)
        return False
    return any((visit(v) for v in graph))

def knapsack_val(p, v, cmax):
    opt = [0] * (cmax + 1)
    for pi, vi in zip(p, v):
        for c in range(cmax, pi - 1, -1):
            opt[c] = max(opt[c], opt[c - pi] + vi)
    return opt[cmax]

def contain_string(haystack: str, needle: str) -> int:
    """Find the first occurrence of needle in haystack.

    Args:
        haystack: The string to search in.
        needle: The string to search for.

    Returns:
        The index of the first occurrence, or -1 if not found.

    Examples:
        >>> contain_string("hello", "ll")
        2"""
    if len(needle) == 0:
        return 0
    if len(needle) > len(haystack):
        return -1
    for index in range(len(haystack)):
        if len(haystack) - index < len(needle):
            return -1
        if haystack[index:index + len(needle)] == needle:
            return index
    return -1

def longest_common_substring(s1, s2):
    """References:
        # https://en.wikibooks.org/wiki/Algorithm_Implementation/Strings/Longest_common_substring#Python2"""
    m = [[0] * (1 + len(s2)) for i in range(1 + len(s1))]
    longest, x_longest = (0, 0)
    for x in range(1, 1 + len(s1)):
        for y in range(1, 1 + len(s2)):
            if s1[x - 1] == s2[y - 1]:
                m[x][y] = m[x - 1][y - 1] + 1
                if m[x][y] > longest:
                    longest = m[x][y]
                    x_longest = x
            else:
                m[x][y] = 0
    return s1[x_longest - longest:x_longest]

def find_duplicate(arr: List[int]) -> int:
    seen_numbers = set()
    for num in arr:
        if num in seen_numbers:
            return num
        seen_numbers.add(num)

def my_max(a: int, b: int) -> int:
    if a > b:
        return a
    return b

def count_permutations(n, r=None):
    """Count the number of permutations of n items taken r at a time

    :param n: total number of items
    :param r: number of items to choose (defaults to n)
    :return: number of permutations"""
    if r is None:
        r = n
    if r > n or r < 0:
        return 0
    if r == 0:
        return 1
    result = 1
    for i in range(n, n - r, -1):
        result *= i
    return result

def minimum_cost_path(matrix: list[list[int]]) -> int:
    """Find the minimum cost traced by all possible paths from top left to bottom right in
    a given matrix

    >>> minimum_cost_path([[2, 1], [3, 1], [4, 2]])
    6

    >>> minimum_cost_path([[2, 1, 4], [2, 1, 3], [3, 2, 1]])
    7"""
    for i in range(1, len(matrix[0])):
        matrix[0][i] += matrix[0][i - 1]
    for i in range(1, len(matrix)):
        matrix[i][0] += matrix[i - 1][0]
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            matrix[i][j] += min(matrix[i - 1][j], matrix[i][j - 1])
    return matrix[-1][-1]

def cuber(num):
    num_cubed = num * num * num
    return num_cubed

def mul(a, b):
    """Same as a * b."""
    return a * b
